// ============================================
// VALIDATION INPUT - MCP Qdrant Search
// RFC-014 context extraction with tracing fields
// ============================================

const input = $input.first().json;
const body = input.body || input;

// Support RFC-014: data in context.* with fallback to root level
const ctx = body.context || {};

const errors = [];

// --- OPTIONAL context fields (tracing only, NO validation errors) ---
const userId = body.user_id || ctx.user_id || null;
const guildId = body.guild_id || ctx.guild_id || null;
const userRequest = body.user_request || ctx.user_request || null;

// --- REQUIRED webhook parameters ---
const query = body.query || ctx.query;
const entityType = body.entity_type || ctx.entity_type;
const qdrantHost = body.qdrant_host || ctx.qdrant_host;
const qdrantPort = body.qdrant_port || ctx.qdrant_port;
const qdrantCollection = body.qdrant_collection || ctx.qdrant_collection;
const openaiApiKey = body.openai_api_key || ctx.openai_api_key || body.plugin_context?.api_keys?.openai;

if (!query) {
  errors.push('query requis');
}
if (!entityType) {
  errors.push('entity_type requis');
}
if (!qdrantHost) {
  errors.push('qdrant_host requis');
}
if (!qdrantPort) {
  errors.push('qdrant_port requis');
}
if (!qdrantCollection) {
  errors.push('qdrant_collection requis');
}
if (!openaiApiKey) {
  errors.push('openai_api_key requis');
}

if (errors.length > 0) {
  return {
    valid: false,
    errors: errors,
    user_id: userId,
    guild_id: guildId,
    user_request: userRequest
  };
}

const qdrantUrl = `http://${qdrantHost}:${qdrantPort}`;

return {
  valid: true,
  query: query,
  entity_type: entityType,
  limit: body.limit || ctx.limit || 10,
  filters: body.filters || ctx.filters || {},
  qdrant_url: qdrantUrl,
  qdrant_collection: qdrantCollection,
  qdrant_api_key: body.qdrant_api_key || ctx.qdrant_api_key || '',
  openai_api_key: openaiApiKey,
  user_id: userId,
  guild_id: guildId,
  user_request: userRequest,
  startTime: Date.now()
};

// ============================================
// BUILD VALIDATION ERROR
// ============================================

const input = $input.first().json;

return {
  success: false,
  _trace: {
    service_response: { validation_errors: input.errors },
    provider: 'openai',
    model: 'text-embedding-3-small',
    mode: 'error',
    latency_ms: 0,
    user_id: input.user_id,
    guild_id: input.guild_id,
    user_request: input.user_request
  },
  error: {
    code: 'VALIDATION_ERROR',
    message: input.errors.join(', '),
    http_status: 400
  },
  user_id: input.user_id,
  guild_id: input.guild_id,
  user_request: input.user_request
};

// ============================================
// FORMAT OUTPUT - MCP Qdrant Search
// With _trace for analyzable webhooks
// ============================================

const input = $input.first().json;
const prevData = $('Validate Input').first().json;
const startTime = prevData.startTime || Date.now();

// --- Context fields for traceability ---
const userId = prevData.user_id;
const guildId = prevData.guild_id;
const userRequest = prevData.user_request;

// Initialize trace
const _trace = {
  service_response: null,
  provider: 'qdrant',
  model: 'text-embedding-3-small',
  latency_ms: 0,
  user_id: userId,
  guild_id: guildId,
  user_request: userRequest
};

try {
  // Handle API errors
  if (input.error || input.status?.error) {
    _trace.service_response = input;
    _trace.latency_ms = Date.now() - startTime;

    return {
      json: {
        success: false,
        error: {
          code: 'SEARCH_ERROR',
          message: input.error?.message || input.status?.error || 'Qdrant search failed',
          http_status: 500
        },
        meta: { provider: 'qdrant', collection: prevData.qdrant_collection },
        user_id: userId,
        guild_id: guildId,
        user_request: userRequest,
        _trace: _trace
      }
    };
  }

  const results = (input.result || []).map(item => ({
    id: item.id,
    score: item.score,
    entity: item.payload || {}
  }));

  // Apply filters if any
  let filtered = results;
  const filters = prevData.filters;

  if (filters.max_time_minutes) {
    filtered = filtered.filter(r => {
      const total = (r.entity.prep_time_minutes || 0) + (r.entity.cook_time_minutes || 0);
      return total <= filters.max_time_minutes;
    });
  }

  if (filters.vegetarian) {
    filtered = filtered.filter(r => r.entity.tags?.includes('vegetarian') || r.entity.tags?.includes('vegetarien'));
  }

  if (filters.vegan) {
    filtered = filtered.filter(r => r.entity.tags?.includes('vegan') || r.entity.tags?.includes('vegan'));
  }

  // Populate trace
  _trace.service_response = input;
  _trace.latency_ms = Date.now() - startTime;

  return {
    json: {
      success: true,
      data: {
        results: filtered,
        total: filtered.length,
        query: prevData.query,
        entity_type: prevData.entity_type
      },
      meta: {
        provider: 'qdrant',
        collection: prevData.qdrant_collection,
        query_embedding_used: true,
        original_count: results.length,
        filtered_count: filtered.length
      },
      user_id: userId,
      guild_id: guildId,
      user_request: userRequest,
      _trace: _trace
    }
  };
} catch (e) {
  _trace.service_response = { error: e.message };
  _trace.latency_ms = Date.now() - startTime;

  return {
    json: {
      success: false,
      error: {
        code: 'PROCESS_ERROR',
        message: 'Failed to process search results: ' + e.message,
        http_status: 500
      },
      meta: { provider: 'qdrant' },
      user_id: userId,
      guild_id: guildId,
      user_request: userRequest,
      _trace: _trace
    }
  };
}
